class stringx {
public:
  stringx();
  stringx(const char *);
  stringx(const stringx &);
  ~stringx();
};
stringx operator+(const char *, const stringx &);
stringx operator+(const stringx &, const char *);

class entity_id {
  unsigned val;
public:
  stringx get_val() const;
};

class entity {
  entity_id id;
public:
  virtual bool is_an_item() const;
  entity_id get_id() const { return id; }
};
class item : public entity {};

typedef entity *vm_entity_t;
typedef item *vm_item_t;

class vm_thread {
public:
  void slf_error(const stringx &);
};

class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char *, int);
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack &, entry_t) { return true; }
  };
};

void error(const stringx &);

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )
#define SLF_DONE return true

class slf_to_item_t : public script_library_class::function
  {
  public:
    struct parms_t
      {
      vm_entity_t e;
      };
    virtual bool operator()( vm_stack &stack, entry_t entry )
      {
      SLF_PARMS;
      vm_item_t result = 0;
      if ( parms->e->is_an_item() )
        result = static_cast<vm_item_t>( parms->e );
      else
        stack.get_thread()->slf_error( "to_item(): " + parms->e->get_id().get_val() + " is not a item" );
      SLF_RETURN;
      SLF_DONE;
      }
  };
